                    console.error('Matricule manquant pour le détail:', detail);
                    frappe.msgprint(__('Matricule manquant pour le détail.'));
                }

            });

            (async function() {
                for (let item of frm.doc.details) {
                    await processItem(item);
                }

                console.log(`Résultat OK: ${fiend}`);
                if (fiend > 0) {
                    let message = (fiend >= 2) ? `${fiend} Enregistrements Modifiés` : `${fiend} Enregistrement Modifié`;
                    frappe.msgprint(__(message));
                }
