frappe.ui.form.on('Preparation Provision Decompte', {
    refresh(frm) {
        // Code de rafraîchissement si nécessaire
    },
    
    période_décompte: function(frm) {
            // Vérifier si une période de décompte est sélectionnée
            if (frm.doc.période_décompte) {
                frappe.call({
                    method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.liste_employees_non_decomptes",
                    args: {
                        'period': frm.doc.période_décompte
                    },
                    callback: function(response) {
                        const data = response.message;
                        if (data && data.length > 0) {
                            // Utiliser la liste des noms d'employés renvoyée
                            const excludedEmployees = data;
                             //frappe.msgprint(__('Ok ' + data));
                            // Filtrer pour exclure les employés déjà décomptés
                            frm.set_query('employee', function() {
                                return {
                                    filters: [
                                        ['Employee', 'name', 'in', excludedEmployees]
                                    ]
                                };
                            });
                        } else {
                            frappe.msgprint(__('Aucun employé à exclure pour cette période.'));
                        }
                    },
                    error: function(err) {
                        console.error('Erreur lors de la récupération:', err);
                        frappe.msgprint(__('Erreur lors de la récupération des employés: ' + err));
                    }
                });
            } else {
                frappe.msgprint(__('Veuillez sélectionner une période avant de choisir un employé.'));
            }
        }

});

